import React from 'react';

const Carousel3D = ({ movies = [], currentIndex, setCurrentIndex }) => {
  const displayMovies = movies.length > 0 ? movies : [
    { id: 0, title: "Dune 2", poster_path: "" },
    { id: 1, title: "Wicked", poster_path: "" },
    { id: 2, title: "Interstellar", poster_path: "" },
    { id: 3, title: "Avatar", poster_path: "" },
    { id: 4, title: "Joker", poster_path: "" },
  ];

  const total = displayMovies.length;

  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);

  return (
    <div className="relative w-full py-8 flex flex-col items-center justify-center bg-[#fbfbfa] overflow-hidden">
      
      {/* 3D 스테이지 영역 */}
      <div 
        className="relative w-full max-w-6xl h-[380px] flex items-center justify-center"
        style={{ perspective: '1800px' }}
      >
        {displayMovies.map((movie, index) => {
          let offset = (index - currentIndex + total) % total;
          if (offset > total / 2) offset -= total;

          const isCenter = offset === 0;

          const translateX = offset * 210; 
          const translateZ = isCenter ? 120 : -Math.abs(offset) * 100;
          const rotateY = offset * -18;
          const scale = isCenter ? 1.25 : Math.max(1 - Math.abs(offset) * 0.12, 0.75);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: total - Math.abs(offset) + (isCenter ? 10 : 0),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.5s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              /* 💡 배경 박스(카드 프레임)를 완전히 제거하고 포스터 이미지 자체에만 그림자와 효과 부여 */
              className={`absolute w-48 h-72 rounded-none overflow-hidden cursor-pointer transition-all duration-500 ${
                isCenter 
                  ? 'shadow-[0_25px_50px_rgba(0,0,0,0.35)] ring-4 ring-[#503396]/30 brightness-100' 
                  : 'shadow-md brightness-75 hover:brightness-90'
              }`}
            >
              {/* 포스터 이미지 (박스 없이 이미지 단독 출력) */}
              {movie.poster_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                  alt={movie.title || 'Movie Poster'} 
                  className="w-full h-full object-cover pointer-events-none rounded-none" 
                />
              ) : (
                <div className="w-full h-full bg-zinc-800 flex flex-col items-center justify-center text-xs text-zinc-200 p-2 text-center font-bold">
                  <span className="mb-1">{movie.title}</span>
                  <span>MOVIE TICKET</span>
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 네비게이션 버튼 */}
      <div className="flex items-center gap-6 mt-4 z-20">
        <button 
          onClick={handlePrev} 
          className="w-9 h-9 rounded-full bg-white text-zinc-800 border border-zinc-300 flex items-center justify-center hover:bg-zinc-100 transition cursor-pointer font-bold shadow-sm text-sm"
        >
          &larr;
        </button>
        <div className="flex gap-2">
          {displayMovies.map((_, idx) => (
            <span 
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-1.5 rounded-full cursor-pointer transition-all ${
                idx === currentIndex ? 'bg-[#503396] w-6' : 'bg-zinc-300 w-1.5'
              }`}
            />
          ))}
        </div>
        <button 
          onClick={handleNext} 
          className="w-9 h-9 rounded-full bg-white text-zinc-800 border border-zinc-300 flex items-center justify-center hover:bg-zinc-100 transition cursor-pointer font-bold shadow-sm text-sm"
        >
          &rarr;
        </button>
      </div>

    </div>
  );
};

export default Carousel3D;
